/* ============================================================
 * 1) (PL/CSQL) Literal Range Validation
 * 2) (PL/CSQL) Internal Arithmetic / Comparison Validation
 *
 * Goals
 *  - FUNCTION RETURN NUMERIC: verify it returns float numeric (domain numeric)
 *  - PROCEDURE DBMS_OUTPUT.put_line: verify output matches server SELECT output
 *  - Ensure PL/CSQL arithmetic/comparison results match server (SQL) results
 *  - Cover scale boundary (-214 ~ 252), overflow, and literal truncation (254 digits)
 * ============================================================ */

--+ server-message on
--;server-output on


evaluate '1. Fixed numeric declaration range validation';
/* ============================================================
 * 1. Fixed numeric declaration range validation (in PL/CSQL)
 * ============================================================ */

-- fixed numeric declaration (prec=38, scale=-84)
DROP TABLE IF EXISTS t_fp_compare;
CREATE OR REPLACE FUNCTION plfn_decl_fixed_ok_1 RETURN NUMERIC
AS
  a NUMERIC(38,-84) := 0;
BEGIN
  RETURN a;
END;

-- Verify function return domain: should be float numeric (domain numeric)
SELECT plfn_decl_fixed_ok_1() AS v, typeof(plfn_decl_fixed_ok_1()) AS t;

-- fixed numeric declaration (prec=38, scale=127)
CREATE OR REPLACE PROCEDURE plpc_decl_fixed_ok_1
AS
  a NUMERIC(38,127) := 0;
BEGIN
  DBMS_OUTPUT.put_line(a);
END;

CALL plpc_decl_fixed_ok_1();

-- out-of-range: scale=128 (compile error -1360)
-- NOTE: run in FAIL script if you want strict pass/fail separation
CREATE OR REPLACE PROCEDURE plpc_decl_fixed_err_scale128
AS
  a NUMERIC(38,128) := 0;
BEGIN
  DBMS_OUTPUT.put_line(a);
END;

-- out-of-range: scale=-85 (compile error -1360)
CREATE OR REPLACE FUNCTION plfn_decl_fixed_err_scale_m85 RETURN NUMERIC
AS
  a NUMERIC(38,-85) := 0;
BEGIN
  RETURN a;
END;


evaluate '2. Float numeric literal / printing: server SELECT vs PL/CSQL';
/* ============================================================
 * 2. Float numeric literal / printing: server SELECT vs PL/CSQL
 *     Compare results by inserting into table
 * ============================================================ */
CREATE OR REPLACE PROCEDURE literal_test() 
AS
    v_neg numeric := -12345.6789;
    v_pos numeric := 12345.6789;
    v_add numeric := 12345.6789 + 0;
    v_sub numeric := 0 - 12345.6789;
    v_mul numeric := 12345.6789 * 1;
    v_fixed numeric(10, 2) := 12345.6789;   -- fixed (기존 동작 유지)
BEGIN
    dbms_output.put_line('v_neg=' || v_neg);
    dbms_output.put_line('v_pos=' || v_pos);
    dbms_output.put_line('v_add=' || v_add);
    dbms_output.put_line('v_sub=' || v_sub);
    dbms_output.put_line('v_mul=' || v_mul);
    dbms_output.put_line('v_fixed=' || v_fixed);
END;

CALL literal_test();

DROP TABLE IF EXISTS t_fp_compare;
CREATE TABLE t_fp_compare (
  test_id VARCHAR(20),
  server_val NUMERIC,
  plcsql_val NUMERIC
);

-- [B-1] Large integer literal (precision > 40 digits -> rounding at 41st digit)

-- (50,0) -> (40,-10)
INSERT INTO t_fp_compare(test_id, server_val)
SELECT 'B1_int_50_0', 12345678901234567890123456789012345678901234567890;

CREATE OR REPLACE PROCEDURE plpc_insert_fp_int_B1_1
AS
  a NUMERIC := 12345678901234567890123456789012345678901234567890;
BEGIN
  UPDATE t_fp_compare SET plcsql_val = a WHERE test_id = 'B1_int_50_0';
END;

CALL plpc_insert_fp_int_B1_1();

